def entities(doc, scope):
    """Return all distinct entity ids (machines, tasks, jobs) in the given scope."""
    scope_node = node_by_title(doc, scope)
    entity_ids = set()
    descriptions = {}
    for nid in scope_node.get("children", []):
        node = node_by_id(doc, nid)
        if node["kind"] == "table":
            if "Machines" in node["title"]:
                for idx, row in table_rows(node):
                    mid = row["machine"]
                    entity_ids.add(mid)
                    descriptions[mid] = f"machine {mid}"
            elif "Task log" in node["title"]:
                for idx, row in table_rows(node):
                    tid = row["task"]
                    jid = row["job"]
                    entity_ids.update([tid, jid])
                    descriptions[tid] = f"task {tid}"
                    descriptions[jid] = f"job {jid}"
    # Convert to list of dicts sorted by id for stability
    return [{"id": eid, "description": descriptions[eid]} for eid in sorted(entity_ids)]


def recorded_end(doc, scope):
    """Return the greatest time referenced in the scope, or None."""
    scope_node = node_by_title(doc, scope)
    max_time = None
    for nid in scope_node.get("children", []):
        node = node_by_id(doc, nid)
        if node["kind"] == "table":
            if "Machines" in node["title"]:
                for _, row in table_rows(node):
                    for col in ("fails at", "returns at"):
                        val = row.get(col)
                        if val and val != "-":
                            t = float(val)
                            if max_time is None or t > max_time:
                                max_time = t
            elif "Task log" in node["title"]:
                for _, row in table_rows(node):
                    t = float(row["time"])
                    if max_time is None or t > max_time:
                        max_time = t
        elif node["kind"] == "list" and "Events" in node["title"]:
            # Extract times from lines like "Time 428: ..."
            import re
            for li in node.get("lines", []):
                m = re.search(r"^Time\s+(\d+)", li)
                if m:
                    t = float(m.group(1))
                    if max_time is None or t > max_time:
                        max_time = t
    return max_time


def inputs(doc, scope):
    """Return all input records (machines and task submissions)."""
    scope_node = node_by_title(doc, scope)
    inp = []
    for nid in scope_node.get("children", []):
        node = node_by_id(doc, nid)
        if node["kind"] == "table":
            if "Machines" in node["title"]:
                for idx, row in table_rows(node):
                    machine = row["machine"]
                    cpu = float(row["CPU"])
                    memory = float(row["memory"])
                    fails_at = row["fails at"]
                    fails_at = None if fails_at == "-" else float(fails_at)
                    returns_at = row["returns at"]
                    returns_at = None if returns_at == "-" else float(returns_at)
                    inp.append({
                        "id": machine,
                        "time": 0.0,
                        "kind": "machine",
                        "entities": [machine],
                        "fields": {
                            "cpu": cpu,
                            "memory": memory,
                            "fails_at": fails_at,
                            "returns_at": returns_at,
                        },
                        "src": [[node["node_id"], idx]],
                    })
            elif "Task log" in node["title"]:
                for idx, row in table_rows(node):
                    if row["event"] == "submit":
                        task = row["task"]
                        job = row["job"]
                        priority = int(row["priority"])
                        cpu = float(row["CPU"])
                        memory = float(row["memory"])
                        runtime = float(row["run time"])
                        inp.append({
                            "id": task,
                            "time": float(row["time"]),
                            "kind": "submission",
                            "entities": [task, job],
                            "fields": {
                                "priority": priority,
                                "cpu": cpu,
                                "memory": memory,
                                "run_time": runtime,
                            },
                            "src": [[node["node_id"], idx]],
                        })
    return inp


def outcomes(doc, scope):
    """Return all process‑generated outcomes (task events and queue state)."""
    scope_node = node_by_title(doc, scope)
    out = []
    for nid in scope_node.get("children", []):
        node = node_by_id(doc, nid)
        if node["kind"] == "table":
            if "Task log" in node["title"]:
                for idx, row in table_rows(node):
                    if row["event"] == "submit":
                        continue  # submit is an input, not a process outcome
                    event = row["event"]
                    task = row["task"]
                    job = row["job"]
                    machine = row["machine"]
                    entities = [task, job]
                    if machine and machine != "-":
                        entities.append(machine)
                    out.append({
                        "time": float(row["time"]),
                        "kind": event,
                        "entities": entities,
                        "value": None,
                        "src": [[node["node_id"], idx]],
                    })
            # Queue state tables
            elif "Queue at window end:" in node["title"]:
                for idx, row in table_rows(node):
                    # Pull out a minimal set of entities for reference
                    task = row.get("task")
                    machine = row.get("machine")
                    entities = []
                    if task:
                        entities.append(task)
                    if machine and machine != "-":
                        entities.append(machine)
                    out.append({
                        "time": None,
                        "kind": "queue_state",
                        "entities": entities,
                        "value": None,
                        "src": [[node["node_id"], idx]],
                    })
    return out


